#include<limits.h>
/*@
assigns \nothing;
ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 1000
#define fun mapavg
#include <assert.h>
/*@
  requires \valid_read(x + (0 .. N-1));
  assigns \nothing;
  ensures \result == \sum(0, N-1, \lambda integer j; j + x[j]) / N;
*/
int mapavg (int x[N])
{
  int i;
  long long ret;
  ret = 0;
  /*@
    loop invariant 0 <= i <= N;
    loop invariant ret == \sum(0, i-1, \lambda integer j; j + x[j]);
    loop assigns i, ret;
    loop variant N - i;
  */
  for (i = 0; i < N; i++) {
    ret = ret+ i + x[i];
  }
  return ret / N;
}
/*@
  assigns x[0 .. N-1], temp, ret, ret2, ret5;
*/
int main ()
{
  int x[N];
  int temp;
  int ret;
  int ret2;
  int ret5;
  /*@
    loop invariant 0 <= i <= N;
    loop assigns i, x[0 .. N-1];
    loop variant N - i;
  */
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  L0: ;
  ret = fun(x);
  //@ assert ret == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L0) / N;
  //@ assert \at(\sum(0, N-1, \lambda integer j; j + x[j]), L0) == (0 + \at(x[0], L0)) + (1 + \at(x[1], L0)) + \at(\sum(2, N-1, \lambda integer j; j + x[j]), L0);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == (0 + x[0]) + (1 + x[1]) + \sum(2, N-1, \lambda integer j; j + x[j]);
  //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L0);
  ret2 = fun(x);
  //@ assert ret2 == \sum(0, N-1, \lambda integer j; j + x[j]) / N;
  //@ assert ret == ret2;
  L1: ;
  temp=x[0];
  /*@
    loop invariant 0 <= i <= N - 1;
    loop invariant \forall integer j; 0 <= j < i ==> x[j] == \at(x[j+1], L1);
    loop invariant \forall integer j; i <= j < N ==> x[j] == \at(x[j], L1);
    loop invariant \sum(0, N-1, \lambda integer j; j + x[j]) == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L1) - \at(x[0], L1) + x[i];
    loop assigns i, x[0 .. N-1];
    loop variant N - 1 - i;
  */
  for(int i =0 ; i<N-1; i++){
     //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == \sum(0, i-1, \lambda integer j; j + x[j]) + (i + x[i]) + \sum(i+1, N-1, \lambda integer j; j + x[j]);
     x[i] = x[i+1];
     //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == \sum(0, i-1, \lambda integer j; j + x[j]) + (i + x[i]) + \sum(i+1, N-1, \lambda integer j; j + x[j]);
  }
  //@ assert \forall integer j; 0 <= j < N - 1 ==> x[j] == \at(x[j+1], L1);
  //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L1) - \at(x[0], L1) + x[N-1];
  x[N-1] = temp;
  //@ assert temp == \at(x[0], L1);
  //@ assert \sum(0, N-1, \lambda integer j; j + x[j]) == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L1);
  ret5 = fun(x);
  //@ assert ret5 == \at(\sum(0, N-1, \lambda integer j; j + x[j]), L1) / N;
  //@ assert ret == ret5;
  //@ assert !(ret != ret2 || ret !=ret5);
  return 1;
}
